 UpdateEngine.Release releaseModel(JSONObject r){JSONArray values=r.optJSONArray("abis");if(values==null)values=r.optJSONArray("abi");java.util.Set<String> abis=new java.util.HashSet<>();if(values!=null)for(int i=0;i<values.length();i++)abis.add(values.optString(i));return new UpdateEngine.Release(r.optInt("versionCode",-1),r.optString("versionName"),r.optString("channel"),r.optString("apkUrl"),r.optString("sha256"),r.optLong("sizeBytes",-1),r.optInt("minSdk",26),r.optInt("maxSdk",0),abis,r.optBoolean("withdrawn"));}
 android.content.pm.Signature[] signatures(android.content.pm.PackageInfo p){return Build.VERSION.SDK_INT>=28?(p.signingInfo==null?null:p.signingInfo.getApkContentsSigners()):p.signatures;}
 UpdateEngine.Identity identity(android.content.pm.PackageInfo p,File archive)throws Exception{
  if(p==null)throw new IOException("Не удалось прочитать APK");java.util.Set<String> certs=new java.util.HashSet<>();android.content.pm.Signature[] signers=signatures(p);if(signers!=null)for(android.content.pm.Signature signer:signers){byte[] hash=MessageDigest.getInstance("SHA-256").digest(signer.toByteArray());StringBuilder hex=new StringBuilder();for(byte b:hash)hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));certs.add(hex.toString());}
  java.util.Set<String> abis=new java.util.HashSet<>();if(archive!=null)try(java.util.zip.ZipFile zip=new java.util.zip.ZipFile(archive)){java.util.Enumeration<? extends java.util.zip.ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){String name=entries.nextElement().getName();if(name.startsWith("lib/")&&name.endsWith(".so")){String[] parts=name.split("/");if(parts.length>=3)abis.add(parts[1]);}}}
  return new UpdateEngine.Identity(p.packageName,p.versionCode,p.applicationInfo==null?1:p.applicationInfo.minSdkVersion,certs,abis);
 }
